import{_ as a,o as l,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"Догоняющая развивающаяся цивилизация","description":"","frontmatter":{},"headers":[],"relativePath":"ru/35-发展中赶超型文明.md","filePath":"ru/35-发展中赶超型文明.md","lastUpdated":1789183869000}'),e={name:"ru/35-发展中赶超型文明.md"};function o(d,t,h,n,s,u){return l(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="догоняющая-развивающаяся-цивилизация" tabindex="-1">Догоняющая развивающаяся цивилизация <a class="header-anchor" href="#догоняющая-развивающаяся-цивилизация" aria-label="Permalink to &quot;Догоняющая развивающаяся цивилизация&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>35</td></tr><tr><td>Модуль</td><td>Типы цивилизаций и социальные системы</td></tr><tr><td>Ключевые слова</td><td>Догоняющий развивающийся, Преимущество догоняющего, Концентрированный прорыв, Стратегическое распределение, Развитие прыжками</td></tr></tbody></table><h2 id="i-происхождение-и-ядро-идеи" tabindex="-1">I. Происхождение и ядро идей <a class="header-anchor" href="#i-происхождение-и-ядро-идеи" aria-label="Permalink to &quot;I. Происхождение и ядро идей&quot;">​</a></h2><p>Догоняющий развивающийся — самый динамичный из пяти типов; истоки — в моделях развития развивающихся стран реального мира. Основа слабая, ресурсы редки, старт поздний; но потенциал огромен, воля сильна. После основания Симбиотической Цивилизации Якоря — успешный опыт догоняющего развития + идеи симбиоза — родился тип.</p><p>Ядро — восемь иероглифов: «догоняющий с опозданием, концентрированный прорыв». Подробно:</p><ol><li><strong>Преимущество догоняющего</strong>: поздний старт — меньше ошибок и затрат; прямое обучение у зрелых; «обгон на поворотах»</li><li><strong>Концентрированный прорыв</strong>: при ограниченных ресурсах — силы на ключевое; прорыв в точках, затем от точки к площади</li><li><strong>Обучение и инновация</strong>: учись у передового, твори по-своему; ни «закрытых дверей», ни «механической копии»</li><li><strong>Постепенное продвижение</strong>: этапные цели, шаг за шагом; стратегическая настойчивость</li></ol><p>Совместимо с ядром: «само-рост» — свой путь; «прогресс Десяти Тысяч Рас» — общее развитие; «Путь для Каждого» — право каждого региона и человека.</p><h2 id="ii-социальная-структура" tabindex="-1">II. Социальная структура <a class="header-anchor" href="#ii-социальная-структура" aria-label="Permalink to &quot;II. Социальная структура&quot;">​</a></h2><p>«Сильное государство + стратегическое планирование + мобилизованное общество + открытое обучение»:</p><table tabindex="0"><thead><tr><th>Элемент</th><th>Характеристика</th><th>Функция</th></tr></thead><tbody><tr><td>Сильное государство</td><td>Планирование и мобилизация; стратегии</td><td>Концентрация, драйв</td></tr><tr><td>Стратегическое планирование</td><td>Средне-долгосрочные планы; этапы и ключевое</td><td>Направление</td></tr><tr><td>Мобилизованное общество</td><td>Коллективное действие</td><td>Поддержка стратегии</td></tr><tr><td>Открытое обучение</td><td>У передовых цивилизаций</td><td>Быстрый рост</td></tr></tbody></table><h3 id="_2-1-сильное-государство" tabindex="-1">2.1 Сильное государство <a class="header-anchor" href="#_2-1-сильное-государство" aria-label="Permalink to &quot;2.1 Сильное государство&quot;">​</a></h3><p>Типичное «государство развития»:</p><ul><li>Стратегии развития</li><li>Концентрация ресурсов</li><li>Крупные проекты</li><li>Быстрые услуги: образование, медицина, жильё</li></ul><p>Ядро — «развитие ведёт государство»: в начале — «локомотив».</p><h3 id="_2-2-стратегическое-планирование" tabindex="-1">2.2 Стратегическое планирование <a class="header-anchor" href="#_2-2-стратегическое-планирование" aria-label="Permalink to &quot;2.2 Стратегическое планирование&quot;">​</a></h3><p>Многоуровневые планы:</p><ul><li>Долгосрочные: десятилетия</li><li>Среднесрочные: 5-10 лет</li><li>Краткосрочные: годовые задачи</li></ul><p>Непрерывность и стабильность; не «смена курса со сменой руководства».</p><h3 id="_2-3-мобилизованное-общество" tabindex="-1">2.3 Мобилизованное общество <a class="header-anchor" href="#_2-3-мобилизованное-общество" aria-label="Permalink to &quot;2.3 Мобилизованное общество&quot;">​</a></h3><ul><li>Коллективное действие</li><li>Гражданская идентичность</li><li>Чувство миссии</li></ul><p>За короткое время — то, на что развитые тратят десятилетия.</p><h3 id="_2-4-открытое-обучение" tabindex="-1">2.4 Открытое обучение <a class="header-anchor" href="#_2-4-открытое-обучение" aria-label="Permalink to &quot;2.4 Открытое обучение&quot;">​</a></h3><ul><li>Системы: Триста Изначальных Систем — с местными поправками</li><li>Управление: опыт развитых</li><li>Таланты и технологии: привлечение</li></ul><p>«На плечах гигантов» — быстрый рост.</p><h2 id="iii-модель-культивации" tabindex="-1">III. Модель культивации <a class="header-anchor" href="#iii-модель-культивации" aria-label="Permalink to &quot;III. Модель культивации&quot;">​</a></h2><p>«Элита ведёт, всеобщее распространение, практическая ориентация»:</p><h3 id="_3-1-элита-ведет" tabindex="-1">3.1 Элита ведёт <a class="header-anchor" href="#_3-1-элита-ведет" aria-label="Permalink to &quot;3.1 Элита ведёт&quot;">​</a></h3><p>Сначала — элита:</p><ul><li>Строгий отбор</li><li>Приоритет ресурсов и наставников</li><li>Прорывные задачи</li></ul><p>Ядро компетенции — быстро.</p><h3 id="_3-2-всеобщее-распространение" tabindex="-1">3.2 Всеобщее распространение <a class="header-anchor" href="#_3-2-всеобщее-распространение" aria-label="Permalink to &quot;3.2 Всеобщее распространение&quot;">​</a></h3><ul><li>Всеобщее базовое образование</li><li>Элита отдаёт обществу: учение, наставничество</li><li>Постепенное расширение</li></ul><p>Массовая база и резерв талантов.</p><h3 id="_3-3-практическая-ориентация" tabindex="-1">3.3 Практическая ориентация <a class="header-anchor" href="#_3-3-практическая-ориентация" aria-label="Permalink to &quot;3.3 Практическая ориентация&quot;">​</a></h3><ul><li>Проблемы реального развития</li><li>Применение — в производственную силу</li><li>Проверка практикой</li></ul><p>Эффективность; без растраты ресурсов.</p><h2 id="iv-подряд-связанныи-с-результатом" tabindex="-1">IV. Подряд, связанный с результатом <a class="header-anchor" href="#iv-подряд-связанныи-с-результатом" aria-label="Permalink to &quot;IV. Подряд, связанный с результатом&quot;">​</a></h2><p>«Стратегический подряд»:</p><ol><li><strong>Стратегический наклон</strong>: к ключевым полям и проектам</li><li><strong>По заслугам</strong>: лучшим — больше</li><li><strong>Поддержка развития</strong>: отстающим регионам — помощь</li><li><strong>Постепенность</strong>: без разовой концентрации</li></ol><p>Плюс: прорыв в ключевом; баланс с общим развитием.</p><h2 id="v-преимущества-и-вызовы" tabindex="-1">V. Преимущества и вызовы <a class="header-anchor" href="#v-преимущества-и-вызовы" aria-label="Permalink to &quot;V. Преимущества и вызовы&quot;">​</a></h2><h3 id="_5-1-преимущества" tabindex="-1">5.1 Преимущества <a class="header-anchor" href="#_5-1-преимущества" aria-label="Permalink to &quot;5.1 Преимущества&quot;">​</a></h3><ul><li><strong>Быстрое развитие</strong>: государство и мобилизация</li><li><strong>Прорыв</strong>: концентрация</li><li><strong>Преимущество догоняющего</strong>: меньше ошибок</li><li><strong>Воля</strong>: устойчивый драйв</li></ul><h3 id="_5-2-вызовы" tabindex="-1">5.2 Вызовы <a class="header-anchor" href="#_5-2-вызовы" aria-label="Permalink to &quot;5.2 Вызовы&quot;">​</a></h3><ul><li><strong>Слабая база</strong>: инфраструктура, системы, таланты</li><li><strong>Дисбаланс</strong>: разрывы регионов и групп</li><li><strong>Устойчивость</strong>: интенсивность против ресурсов</li><li><strong>Зрелость институтов</strong>: постоянное улучшение</li></ul><p>Ответ: вбирает лучшее — социальную защиту североевропейского, инновации североамериканского; баланс скорости и качества.</p><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Самый динамичный тип: «догоняющий с опозданием, концентрированный прорыв»; сильное государство, планирование, мобилизация, открытость; элита + всеобщность; стратегический подряд. Сохраняя своё, улучшает институты — к качеству и балансу.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>30-五种共生文明分型总览 (Обзор пяти типов симбиотических цивилизаций)</li><li>31-东亚集约型文明 (Восточноазиатская интенсивная цивилизация)</li><li>36-社会结构与阶层流动 (Социальная структура и мобильность классов)</li></ul>',50)])])}const c=a(e,[["render",o]]);export{_ as __pageData,c as default};
